import { compareEquipment } from './gear-comparison.js';
import { renderLoadoutComparison } from './equipment-comparison-ui.js';
import { actionCostView, actionCostDetails, renderActionCostHelp } from './action-costs.js';
import { workshopView, workshopTier } from './workshop.js';
import { settlementServices, serviceAccepts } from './world-services.js';
import { renderAvatar } from './avatar.js';
import { renderCarriedArt } from './item-art.js';
import { GEAR_CATALOG, getGearItem } from './gear.js';
import { SLOT_NAMES } from './gear-loot.js';

export function craftEquipmentComparison(s,row,finish='plain'){
 if(!row?.item)return null;if(finish==='plain')return compareEquipment(s,row.item.id);
 const id='found_craft_preview',record={id,baseId:row.item.id,quality:'uncommon',affix:finish,tier:1,source:s.locationId,day:s.day,crafted:true},view={...s,equipment:{...s.equipment,owned:[...s.equipment.owned],instances:[...(s.equipment.instances||[]),record]}};
 return compareEquipment(view,id);
}
export const CRAFTING_TABS=[['equipment','Equipment'],['buildings','Construction'],['patterns','Patterns'],['services','Other Work']];
export function currentCraftSession(s,session){const r=session&&settlementServices(s).find(r=>r.id===session.serviceId&&r.kind==='smith'&&r.here&&r.personId===session.personId);return r&&session.locationId===s.locationId?session:null;}
export function newCraftSession(s,r){return {serviceId:r.id,personId:r.personId,locationId:s.locationId,mode:'craft',category:'equipment',filter:'all',query:'',finish:'plain',selected:null};}
export function craftRows(s,actions,session){
 const v=workshopView(s),r=settlementServices(s).find(r=>r.id===session.serviceId&&r.kind==='smith'&&r.here),offered=actions.filter(a=>r&&serviceAccepts(r,a.id));
 const row=(a,extra={})=>({...a,days:a.durationDays??a.days??0,cost:a.quotedCost??a.cost??0,...extra,disabledReason:actions.find(x=>x.id===a.id)?.disabledReason||a.disabledReason||(!actions.some(x=>x.id===a.id)?'Resolve your current moment before beginning this work.':null)});
 const legacy=GEAR_CATALOG.filter(i=>i.recipe&&!i.workshopTier).map(item=>{const a=offered.find(a=>a.id==='gear_craft_'+item.id);return row(a||{id:'gear_craft_'+item.id,label:'Craft '+item.name,description:item.description,days:2,cost:item.recipe.gold,disabledReason:s.equipment.owned.includes(item.id)?'You already own '+item.name+'.':'This design is not available right now.'},{name:item.name,item,slot:getGearItem(s,item.id)?.slot||item.slot,tier:1,skill:0,materials:Object.fromEntries(Object.entries(item.recipe).filter(([id,n])=>id!=='gold'&&n>0)),output:'1 '+item.name+' · +1 Craftsmanship',details:item.description});});
 if(session.category==='equipment')return [...(session.finish==='plain'?legacy:[]),...v.recipes.map(recipe=>{const choice=session.finish==='plain'?recipe:recipe.finishes.find(f=>f.id===session.finish)||recipe,item=GEAR_CATALOG.find(i=>i.id===recipe.itemId),a=offered.find(a=>a.id===choice.actionId);return row(a||{id:choice.actionId,label:choice.name,description:choice.description,days:choice.days,cost:choice.cost,materials:choice.materials,disabledReason:choice.disabledReason},{name:recipe.name,item,slot:recipe.slot,tier:choice.tier,skill:choice.requiredCrafting,materials:choice.materials,output:session.finish==='plain'?'1 '+recipe.name+' · +1 Craftsmanship':choice.quote.quality+' '+recipe.name+' · +1 Craftsmanship',details:choice.description});})];
 if(session.category==='buildings')return v.buildings.map(b=>row(offered.find(a=>a.id===b.actionId)||{id:b.actionId,label:b.name,days:b.days,cost:b.cost,materials:b.materials,disabledReason:b.disabledReason},{name:b.name,tier:0,skill:b.requiredCrafting,materials:b.materials,output:'1 '+b.name+' here · +1 Craftsmanship',details:b.description+' '+b.benefit}));
 return offered.filter(a=>session.category==='patterns'?a.id.startsWith('workshop_pattern_'):!/^(?:workshop_(craft_|fitted_|build_|pattern_|gather_|continue$|cancel$)|gear_craft_)/.test(a.id)).map(a=>row(a,{name:a.label,skill:a.requirements?.crafting??null,tier:a.requirements?.workshopTier||0,materials:a.materials??null,output:a.description,details:''}));
}
// UI quotes bind the reviewed recipe to this life, day, actual artisan and resources.
// Confirmation still uses the authoritative engine action and all of its gates.
export function craftQuote(s,actions,session){const a=craftRows(s,actions,session).find(a=>a.id===session.selected);return a?JSON.stringify({id:a.id,day:s.day,life:s.seed+':'+(s.timeline?.birthDay||0)+':'+(s.dynasty?.generation||1),service:session.serviceId,person:session.personId,location:s.locationId,gold:s.hero.gold,materials:s.equipment.materials,owned:s.equipment.owned,instances:s.equipment.instances,project:s.workshop.project,crafting:s.workshop.crafting,tier:workshopTier(s),action:a}):null;}
export function renderCraftingWindow(s,r,actions,ui){
 const {e,button}=ui,session=currentCraftSession(s,ui.craftSession);if(!session)return '';
 const v=workshopView(s),rows=craftRows(s,actions,session),query=session.query.trim().toLowerCase(),shown=rows.filter(a=>(session.filter==='all'||a.slot===session.filter)&&(!query||(a.name+' '+a.details).toLowerCase().includes(query))),selected=rows.find(a=>a.id===session.selected);
 const art=a=>renderCarriedArt(a.item?{id:'gear:'+a.item.id,item:a.item}:{id:a.id,name:a.name},e);
 const project=s.workshop?.project,continuation=actions.find(a=>a.id==='workshop_continue');
 const progress=project?`<section class="craft-project" role="status"><span class="eyebrow">WORK IN PROGRESS</span><h4>${e(project.title)}</h4><p>${project.remainingDays} of ${project.totalDays} Days Remain · Supplies and Gold Already Committed</p>${button('Continue Project','craft-continue','workshop_continue','primary',!continuation||Boolean(continuation.disabledReason))}${continuation?.disabledReason?`<p class="disabled-reason">${e(continuation.disabledReason)}</p>`:''}<p class="small-copy">Interruptions keep this project saved. Continue here without paying the committed fee or materials again. Household living costs still accrue as the remaining days pass.</p>${continuation?`<p class="small-copy">${e(actionCostDetails(s,continuation))}</p>`:''}<details><summary>Abandon Project</summary><p class="small-copy">Committed Gold and materials will not be refunded; unfinished output is lost.</p>${button('Abandon This Work','craft-continue','workshop_cancel','ghost small',!actions.some(a=>a.id==='workshop_cancel'&&!a.disabledReason))}</details></section>`:'';
 const materials=Object.entries(selected?.materials||{}).filter(([,n])=>n>0),quote=selected?actionCostView(s,selected):null;
 const details=selected?`<div class="craft-result-art">${art(selected)}</div><span class="eyebrow">${session.category==='patterns'?'PATTERN TO LEARN':'REVIEW YOUR WORK'}</span><h4 id="craft-item-heading" tabindex="-1">${e(selected.name)}</h4>${selected.details?`<p>${e(selected.details)}</p>`:''}<dl class="craft-terms"><div><dt>Result</dt><dd>${e(selected.output)}</dd></div><div><dt>Time</dt><dd>${selected.days||0} Day${selected.days===1?'':'s'}</dd></div><div><dt>Direct Fee</dt><dd>${selected.cost||0} Gold · You Have ${s.hero.gold}</dd></div>${quote.household&&quote.days>0?`<div><dt>Expected Living-Cost Accrual</dt><dd>+${quote.household.additionalCost} Gold over this time · Settled separately from the fee</dd></div>`:''}${selected.skill!==null?`<div><dt>Craftsmanship</dt><dd>${selected.skill||0} Required · Yours ${v.crafting}</dd></div>`:''}${selected.tier?`<div><dt>Workbench</dt><dd>Tier ${selected.tier} Required · Here ${workshopTier(s)}</dd></div>`:''}</dl>${selected.item?renderLoadoutComparison(craftEquipmentComparison(s,selected,session.finish),ui,{id:selected.id,label:selected.name,context:'If crafted and equipped. Crafting leaves your current loadout unchanged.'}):''}<h5>Materials Needed</h5>${materials.length?`<div class="craft-ingredients">${materials.map(([id,n])=>`<div class="craft-ingredient ${(s.equipment.materials[id]||0)<n?'missing':''}">${renderCarriedArt({id:'material:'+id,name:id},e)}<span>${e(v.materials.find(m=>m.id===id)?.label||id)}<small>${n} Required · ${s.equipment.materials[id]||0} Owned</small></span></div>`).join('')}</div>`:selected.materials===null?'<p class="small-copy">See the work description for specific requirements.</p>':'<p class="small-copy">No materials required.</p>'}${renderActionCostHelp(s,ui,'craft-costs')}<div class="craft-confirm">${button(session.category==='equipment'?'Craft':session.category==='buildings'?'Build':session.category==='patterns'?'Study Pattern':'Begin Work','craft-confirm',selected.id,'primary',Boolean(selected.disabledReason))}<p role="status" class="${selected.disabledReason?'disabled-reason':'small-copy'}">${e(selected.disabledReason||'Review the result and costs. Nothing is spent until you confirm.')}</p></div><p class="small-copy">${session.category==='equipment'?'Finished equipment goes into Inventory. Nothing is equipped automatically.':'Work uses the existing calendar and saved project rules.'}</p>`:'<div class="craft-empty"><span class="eyebrow">AT THE WORKBENCH</span><h4>Choose What to Make</h4><p>Inspect a design to see its result, your materials, direct fee, time and expected household accrual before beginning.</p></div>';
 return `<section class="service-meeting crafting-meeting" data-service-person="${e(r.personId)}"><div class="trade-workspace craft-workspace"><header class="trade-heading"><div class="trade-merchant">${renderAvatar(r.person,{size:'small',age:r.person.age})}<div><span class="eyebrow">THE CRAFTSPERSON’S WORKBENCH</span><h3 id="craft-heading" tabindex="-1">Craft with ${e(r.name)}</h3></div></div>${button('Back to Conversation','craft-conversation','','ghost small')}</header><div class="craft-summary"><span>Craftsmanship <strong>${v.crafting}</strong></span><span>Workbench <strong>Tier ${workshopTier(s)}</strong></span><span>Your Gold <strong>${s.hero.gold}</strong></span></div>${progress}<nav class="craft-tabs" aria-label="Crafting Categories">${CRAFTING_TABS.map(([id,label])=>button(label,'craft-category',id,`ghost small ${session.category===id?'active':''}`,false,session.category===id)).join('')}</nav><form id="craft-search" class="trade-toolbar"><label class="sr-only" for="craft-query">Search Designs</label><input id="craft-query" name="query" type="search" placeholder="Search Designs" value="${e(session.query)}">${session.category==='equipment'?`<label>Slot<select name="slot">${[['all','All Slots'],...Object.entries(SLOT_NAMES)].map(([id,label])=>`<option value="${e(id)}" ${session.filter===id?'selected':''}>${e(label)}</option>`).join('')}</select></label><label>Finish<select name="finish"><option value="plain" ${session.finish==='plain'?'selected':''}>Standard Design</option>${v.patterns.map(p=>`<option value="${p.id}" ${session.finish===p.id?'selected':''}>${e(p.name)}${p.learned?'':' · Study First'}</option>`).join('')}</select></label>`:''}<button type="submit" class="button secondary small">Find</button>${session.query||session.filter!=='all'?button('Clear search &amp; slot filter','craft-clear','','ghost small'):''}</form><div class="craft-columns"><section class="craft-catalog-pane" aria-label="Available Designs"><h4>${e(CRAFTING_TABS.find(([id])=>id===session.category)?.[1]||'Designs')} <small>${shown.length} matching of ${rows.length} designs</small></h4><div class="trade-item-grid craft-design-grid">${shown.map(a=>`<button type="button" class="trade-cell ${a.disabledReason?'untradeable':''} ${a.id===session.selected?'selected':''}" data-op="craft-item" data-id="${e(a.id)}" aria-pressed="${a.id===session.selected}" aria-label="${e(a.name+' · '+(a.cost||0)+' Gold · '+(a.days||0)+' Days'+(a.disabledReason?' · '+a.disabledReason:''))}">${art(a)}<span class="trade-item-name">${e(a.name)}</span><small>${a.cost||0}g · ${a.days||0}d${a.disabledReason?' · Locked':''}</small></button>`).join('')}</div>${shown.length?'':'<p class="small-copy">No designs match these filters. Clear the search or choose another slot or category to see its requirements.</p>'}</section><section class="craft-detail" aria-label="Selected Design">${details}</section></div><details class="craft-stock"><summary>Your Material Store</summary><div class="resource-grid">${v.materials.map(m=>`<div><span>${e(m.label)}</span><strong>${m.amount}</strong></div>`).join('')}</div><p class="small-copy">These are the same carried materials used by commissions. A Materials Merchant at the Market supplies bundles.</p></details></div></section>`;
}
